import{_ as e,o as t,c as r,a2 as a}from"./chunks/framework.BZO4qERu.js";const g=JSON.parse('{"title":"Discord","description":"","frontmatter":{},"headers":[],"relativePath":"zh/integrations/channels/discord.md","filePath":"zh/integrations/channels/discord.md","lastUpdated":1790952322000}'),l={name:"zh/integrations/channels/discord.md"};function i(s,o,d,n,c,h){return t(),r("div",null,[...o[0]||(o[0]=[a('<h1 id="discord" tabindex="-1">Discord <a class="header-anchor" href="#discord" aria-label="Permalink to &quot;Discord&quot;">​</a></h1><p>把 Memoh Bot 接到 Discord，进服务器，在频道和私聊里与社群成员对话。</p><h2 id="前提条件" tabindex="-1">前提条件 <a class="header-anchor" href="#前提条件" aria-label="Permalink to &quot;前提条件&quot;">​</a></h2><ul><li>一个能登录 <a href="https://discord.com/developers/applications" target="_blank" rel="noreferrer">Discord Developer Portal</a> 的 Discord 账号。</li><li>一个可以授权 Bot 加入的服务器。</li><li>一个 Memoh Bot；渠道在它的 <strong>平台</strong> 标签页里配置。</li></ul><h2 id="步骤" tabindex="-1">步骤 <a class="header-anchor" href="#步骤" aria-label="Permalink to &quot;步骤&quot;">​</a></h2><h3 id="_1-在-discord-developer-portal-创建应用并拿-bot-token" tabindex="-1">1. 在 Discord Developer Portal 创建应用并拿 Bot Token <a class="header-anchor" href="#_1-在-discord-developer-portal-创建应用并拿-bot-token" aria-label="Permalink to &quot;1. 在 Discord Developer Portal 创建应用并拿 Bot Token&quot;">​</a></h3><ol><li>打开 <a href="https://discord.com/developers/applications" target="_blank" rel="noreferrer">Discord Developer Portal</a>。</li><li>点 <strong>New Application</strong>，起名。</li><li>左侧进入 <strong>Bot</strong>。</li><li>点 <strong>Reset Token</strong> 生成 <strong>Bot Token</strong>，复制并妥善保管。</li></ol><h3 id="_2-在-discord-developer-portal-开启特权意图" tabindex="-1">2. 在 Discord Developer Portal 开启特权意图 <a class="header-anchor" href="#_2-在-discord-developer-portal-开启特权意图" aria-label="Permalink to &quot;2. 在 Discord Developer Portal 开启特权意图&quot;">​</a></h3><ol><li>在 <strong>Bot</strong> 页向下找到 <strong>Privileged Gateway Intents</strong>。</li><li>开启 <code>Message Content Intent</code>、<code>Server Members Intent</code> 和 <code>Presence Intent</code>。</li><li>保存。</li></ol><h3 id="_3-在-discord-developer-portal-生成邀请链接-把-bot-拉进服务器" tabindex="-1">3. 在 Discord Developer Portal 生成邀请链接，把 Bot 拉进服务器 <a class="header-anchor" href="#_3-在-discord-developer-portal-生成邀请链接-把-bot-拉进服务器" aria-label="Permalink to &quot;3. 在 Discord Developer Portal 生成邀请链接，把 Bot 拉进服务器&quot;">​</a></h3><ol><li>进入 <strong>OAuth2</strong> &gt; <strong>URL Generator</strong>。</li><li>勾选 scope：<code>bot</code>、<code>applications.commands</code>。</li><li>勾选权限：<code>Send Messages</code>、<code>Read Message History</code>、<code>Embed Links</code>、<code>Attach Files</code>。</li><li>复制生成的 URL，在浏览器里打开。</li><li>选择要加入的服务器并授权。</li></ol><blockquote><p>官方说明：<a href="https://discord.com/developers/docs/intro" target="_blank" rel="noreferrer">Discord Developer Portal - Bots</a></p></blockquote><h3 id="_4-在-memoh-添加-discord-渠道" tabindex="-1">4. 在 Memoh 添加 Discord 渠道 <a class="header-anchor" href="#_4-在-memoh-添加-discord-渠道" aria-label="Permalink to &quot;4. 在 Memoh 添加 Discord 渠道&quot;">​</a></h3><ol><li>打开 Bot 详情页，进入 <strong>平台</strong> 标签页。</li><li>点 <strong>Add Channel</strong>，选 <strong>Discord</strong>。</li><li>贴上 <strong>Bot Token</strong>。</li><li>点 <strong>Save and Enable</strong>。</li></ol><h2 id="凭据" tabindex="-1">凭据 <a class="header-anchor" href="#凭据" aria-label="Permalink to &quot;凭据&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td><strong>Bot Token</strong></td><td>在应用的 <strong>Bot</strong> 页用 <strong>Reset Token</strong> 生成，妥善保管。</td></tr></tbody></table><h2 id="验证" tabindex="-1">验证 <a class="header-anchor" href="#验证" aria-label="Permalink to &quot;验证&quot;">​</a></h2><p>私聊 Bot 发送 <code>/help</code>，或在 Bot 已加入的服务器频道里 @它。Bot 回复命令列表即说明渠道已生效。</p><h2 id="群聊" tabindex="-1">群聊 <a class="header-anchor" href="#群聊" aria-label="Permalink to &quot;群聊&quot;">​</a></h2><p>Discord 服务器即群聊场景。Bot 授权进入服务器后，在频道里 @它即可对话。</p><h2 id="停用与更换凭据" tabindex="-1">停用与更换凭据 <a class="header-anchor" href="#停用与更换凭据" aria-label="Permalink to &quot;停用与更换凭据&quot;">​</a></h2><p>在 Bot 的 <strong>平台</strong> 标签页可以随时停用或移除该渠道。更换 token 时，更新 <strong>Bot Token</strong> 字段并保存即可。</p>',22)])])}const b=e(l,[["render",i]]);export{g as __pageData,b as default};
